package com.kareem.cortex;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import java.io.File;
import java.util.*;

public class VaultActivity extends Activity {
    VaultDb db;LinearLayout feed,tabs;String filter="ALL";int bg=Color.rgb(11,12,14),surface=Color.rgb(24,26,30),text=Color.rgb(245,244,240),muted=Color.rgb(156,159,168),accent=Color.rgb(232,177,72),danger=Color.rgb(246,124,118),ok=Color.rgb(120,205,150),border=Color.rgb(47,50,57);
    int dp(int x){return(int)(x*getResources().getDisplayMetrics().density+.5f);}TextView plain(String s,int sp,int c){TextView v=new TextView(this);v.setTextSize(sp);v.setTextColor(c);CortexTextUi.setPlain(v,s);return v;}TextView readable(String s,int sp,int c){TextView v=new TextView(this);v.setTextSize(sp);v.setTextColor(c);CortexTextUi.setReadable(v,s);return v;}GradientDrawable round(int fill,int stroke,int r){GradientDrawable g=new GradientDrawable();g.setColor(fill);g.setCornerRadius(dp(r));g.setStroke(dp(1),stroke);return g;}
    @Override public void onCreate(Bundle b){super.onCreate(b);db=new VaultDb(this);ScreenshotLearning.ensure(db);VisualInsightStore.ensure(db);V43Maintenance.run(this,db);build();refresh();}
    @Override protected void onResume(){super.onResume();if(db!=null)refresh();ScreenshotWorkScheduler.kick(this);}
    void build(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);root.setPadding(dp(16),dp(16),dp(16),0);TextView h=plain("VAULT",28,text);h.setTypeface(null,1);root.addView(h);TextView s=plain("Original evidence plus useful derived understanding. The original image always remains the source of truth.",13,muted);s.setPadding(0,dp(3),0,dp(12));root.addView(s);HorizontalScrollView hsv=new HorizontalScrollView(this);hsv.setHorizontalScrollBarEnabled(false);tabs=new LinearLayout(this);tabs.setOrientation(LinearLayout.HORIZONTAL);hsv.addView(tabs);root.addView(hsv,new LinearLayout.LayoutParams(-1,dp(44)));ScrollView sv=new ScrollView(this);feed=new LinearLayout(this);feed.setOrientation(LinearLayout.VERTICAL);sv.addView(feed);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
    void refresh(){tabs.removeAllViews();String[] fs={"ALL","VOICE","SCREENSHOTS","FILES","TEXT"};for(String f:fs)addTab(f);feed.removeAllViews();ArrayList<KnowledgeItem> all=db.lexicalSearch("",2000);int shown=0;for(KnowledgeItem k:all){if(!match(k))continue;addCard(k);shown++;}if(shown==0){TextView e=plain("No captures in this view yet.",14,muted);e.setPadding(dp(8),dp(40),dp(8),dp(40));feed.addView(e);}}
    void addTab(String f){TextView t=plain(f,10,f.equals(filter)?accent:muted);t.setGravity(Gravity.CENTER);if(f.equals(filter))t.setTypeface(null,1);t.setBackground(round(surface,f.equals(filter)?accent:border,999));t.setOnClickListener(v->{filter=f;refresh();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(34));p.setMargins(0,0,dp(7),0);p.width=dp(Math.max(68,f.length()*9+24));tabs.addView(t,p);}
    boolean match(KnowledgeItem k){if("ALL".equals(filter))return true;if("VOICE".equals(filter))return "AUDIO".equals(k.type);if("SCREENSHOTS".equals(filter))return isShot(k);if("FILES".equals(filter))return "FILE".equals(k.type);return !"AUDIO".equals(k.type)&&!isShot(k)&&!"FILE".equals(k.type);}boolean isShot(KnowledgeItem k){return "SCREENSHOT".equals(k.type)||"IMAGE".equals(k.type);}
    void addCard(KnowledgeItem k){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(15),dp(14),dp(15),dp(14));c.setBackground(round(surface,border,20));c.setClickable(true);c.setOnClickListener(v->detail(k));TextView t=readable(clean(k.title),16,text);t.setTypeface(null,1);t.setMaxLines(2);c.addView(t);TextView meta=plain(friendly(k.type)+" • "+k.source+" • "+age(captureTime(k))+" • "+statusLabel(k),11,statusColor(k));meta.setPadding(0,dp(5),0,0);c.addView(meta);
        if(isShot(k)){VisualInsightStore.Insight vi=VisualInsightStore.get(db,k.id);if(vi!=null&&vi.ready()){TextView x=readable("Cortex sees: "+clip(vi.description,220),13,text);x.setPadding(0,dp(9),0,0);x.setMaxLines(4);c.addView(x);TextView u=plain("Visual Intelligence • "+vi.contentType.replace('_',' ')+" • usefulness "+vi.usefulnessScore+"/100",11,accent);u.setPadding(0,dp(7),0,0);c.addView(u);}else{String raw=raw(k);if(!raw.isEmpty()){TextView b=readable(clip(raw,180),13,muted);b.setPadding(0,dp(9),0,0);b.setMaxLines(3);c.addView(b);}TextView x=plain("Visual understanding: "+(vi==null?"not run yet":vi.status.replace('_',' ')),11,muted);x.setPadding(0,dp(7),0,0);c.addView(x);}}
        else{String raw=raw(k);if(!raw.isEmpty()){TextView b=readable(clip(raw,220),13,text);b.setPadding(0,dp(9),0,0);b.setMaxLines(4);c.addView(b);}}
        LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,dp(10));feed.addView(c,p);}
    String statusLabel(KnowledgeItem k){if("analyzed".equals(k.status))return isShot(k)?"Stored + searchable":"Analyzed";if("queued".equals(k.status))return "Queued";if("analyzing".equals(k.status))return "Analyzing";if("analysis_failed".equals(k.status)||"failed_retryable".equals(k.status))return "Analysis failed";return k.status==null?"":k.status;}int statusColor(KnowledgeItem k){if("analyzed".equals(k.status))return ok;if("analysis_failed".equals(k.status)||"failed_retryable".equals(k.status))return danger;return muted;}

    void detail(KnowledgeItem k){ScrollView sv=new ScrollView(this);LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(dp(18),dp(8),dp(18),dp(18));sv.addView(b);
        if(isShot(k)&&k.attachmentPath!=null&&!k.attachmentPath.isEmpty()){ImageView im=new ImageView(this);im.setAdjustViewBounds(true);im.setScaleType(ImageView.ScaleType.FIT_CENTER);Bitmap bmp=preview(k.attachmentPath);if(bmp!=null)im.setImageBitmap(bmp);b.addView(im,new LinearLayout.LayoutParams(-1,-2));}
        label(b,"SOURCE");b.addView(plain(friendly(k.type)+" • "+k.source+"\nCaptured: "+new java.text.SimpleDateFormat("dd MMM yyyy • HH:mm",Locale.getDefault()).format(new Date(captureTime(k)))+"\nStatus: "+statusLabel(k),12,muted));
        if(isShot(k)){VisualInsightStore.Insight vi=VisualInsightStore.get(db,k.id);label(b,"VISUAL INTELLIGENCE");if(vi!=null&&vi.ready()){b.addView(readable("What Cortex sees\n"+empty(vi.description,"No description")+"\n\nWhy it may matter\n"+empty(vi.usefulnessReason,"No strong usefulness signal")+"\n\nType: "+vi.contentType.replace('_',' ')+" • usefulness "+vi.usefulnessScore+"/100",13,text));ArrayList<String> acts=vi.actionLabels();if(!acts.isEmpty()){label(b,"USEFUL ACTIONS");b.addView(readable(bullets(acts),12,text));}if(!vi.visibleText.trim().isEmpty()){label(b,"VISIBLE TEXT FROM VISION");b.addView(readable(vi.visibleText,13,text));}}else b.addView(readable(vi==null?"This image has not had strong visual understanding yet.":"Visual status: "+vi.status+(vi.error.isEmpty()?"":"\n"+vi.error),12,muted));Button inspect=button(vi!=null&&vi.ready()?"OPEN VISUAL INTELLIGENCE":"UNDERSTAND THIS IMAGE");inspect.setOnClickListener(v->{Intent i=new Intent(this,VisualIntelligenceActivity.class);i.putExtra("item_id",k.id);startActivity(i);});LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(-1,dp(48));ip.setMargins(0,dp(10),0,0);b.addView(inspect,ip);}
        if(k.extractedText!=null&&!k.extractedText.trim().isEmpty()){label(b,"SUPPORTING EXTRACTED TEXT");b.addView(readable(k.extractedText,13,muted));}if(k.summary!=null&&!k.summary.trim().isEmpty()){label(b,"LEGACY / LOCAL SUMMARY");b.addView(readable(k.summary,13,muted));}
        if(isShot(k)){ArrayList<String> chosen=ScreenshotLearning.selected(db,k.id);String type=ScreenshotLearning.contentType(db,k.id);label(b,"WHAT MATTERS TO YOU");b.addView(readable(chosen.isEmpty()?"Not taught manually yet.":bullets(chosen),12,chosen.isEmpty()?muted:text));Button teach=button("TEACH CORTEX WHAT MATTERS");teach.setOnClickListener(v->teach(k));b.addView(teach,new LinearLayout.LayoutParams(-1,dp(48)));}
        new AlertDialog.Builder(this).setTitle(clean(k.title)).setView(sv).setNegativeButton("Close",null).show();}
    Button button(String s){Button b=new Button(this);b.setText(s);b.setTextSize(11);b.setTextColor(text);b.setAllCaps(false);b.setBackground(round(surface,border,16));return b;}
    void teach(KnowledgeItem k){String type=ScreenshotLearning.contentType(db,k.id);String[] opts=ScreenshotLearning.options(type);boolean[] checked=ScreenshotLearning.suggested(db,type,opts);for(String old:ScreenshotLearning.selected(db,k.id))for(int i=0;i<opts.length;i++)if(opts[i].equals(old))checked[i]=true;new AlertDialog.Builder(this).setTitle("What matters here? • "+type).setMultiChoiceItems(opts,checked,(d,w,on)->checked[w]=on).setPositiveButton("Save",(d,w)->{ScreenshotLearning.record(db,k.id,type,opts,checked);Toast.makeText(this,"Cortex learned your priorities",Toast.LENGTH_LONG).show();refresh();}).setNegativeButton("Cancel",null).show();}
    Bitmap preview(String path){try{File f=new File(path);BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeFile(f.getAbsolutePath(),o);int sample=1;while(Math.max(o.outWidth,o.outHeight)/sample>1600)sample*=2;BitmapFactory.Options d=new BitmapFactory.Options();d.inSampleSize=sample;return BitmapFactory.decodeFile(f.getAbsolutePath(),d);}catch(Exception e){return null;}}
    long captureTime(KnowledgeItem k){if(k.metadataJson!=null&&!k.metadataJson.isEmpty())try{org.json.JSONObject o=new org.json.JSONObject(k.metadataJson);long x=o.optLong("source_modified",0);if(x>0)return x;}catch(Exception ignored){}return k.createdAt;}
    void label(LinearLayout p,String s){TextView h=plain(s,11,accent);h.setTypeface(null,1);h.setPadding(0,dp(14),0,dp(6));p.addView(h);}String raw(KnowledgeItem k){if(k.rawText!=null&&!k.rawText.trim().isEmpty())return k.rawText;if(k.extractedText!=null&&!k.extractedText.trim().isEmpty())return k.extractedText;return k.summary==null?"":k.summary;}String clean(String s){if(s==null||s.trim().isEmpty())return "Memory";String x=s.trim();if(x.regionMatches(true,0,"Voice:",0,6))x=x.substring(6).trim();return x;}String friendly(String s){if("AUDIO".equals(s))return "Voice";if("SCREENSHOT".equals(s))return "Screenshot";if("IMAGE".equals(s))return "Image";return s==null?"Memory":s;}String clip(String s,int n){return s==null?"":(s.length()<=n?s:s.substring(0,n)+"…");}String bullets(ArrayList<String> xs){StringBuilder s=new StringBuilder();for(String x:xs)s.append("• ").append(x).append('\n');return s.toString().trim();}String age(long ms){long m=Math.max(0,System.currentTimeMillis()-ms)/60000;if(m<1)return "now";if(m<60)return m+"m";long h=m/60;if(h<24)return h+"h";return h/24+"d";}String empty(String s,String f){return s==null||s.trim().isEmpty()?f:s.trim();}
}
